registerRefData('nsw-cond-n-689',{"id":689,"pan":null,"ref":"DA/1127/2023","address":"38 Yorston Street Warners Bay 2282,40 Yorston Street Warners Bay 2282","description":"Centre-based child care facility","outcome":"approved","outcome_raw":"Approved","outcome_source":"planning_panels","determined":"2024-07-12","notice_url":"https://apps.planningportal.nsw.gov.au/prweb/PRRestService/DocMgmt/v1/PublicDocuments/DATA-WORKATTACH-FILE PEC-DPE-EP-WORK PPSHCC-223!20240712T043853.691 GMT","sha256":"23ea721edb246bb5c3093958efd56e4aeadaabc9d2c91fd6486eff6dec83eb58","pages":26,"layout":"numbered","n":72,"fetched_at":"2026-08-16T23:19:06+00:00","file":"n/689.js","source_page":"https://www.planningportal.nsw.gov.au/planning-panel/centre-based-child-care-facility","lga":"LAKE MACQUARIE","conditions":[{"label":"1","code":null,"number":"1","title":"","text":"PANEL REF - LGA - DA NO. PPSHCC-223 - Lake Macquarie - DA/1127/2023","stage":"general","stage_basis":"heading","page":3},{"label":"2","code":null,"number":"2","title":"PROPOSED DEVELOPMENT Childcare Facility","text":"","stage":"general","stage_basis":"heading","page":3},{"label":"3","code":null,"number":"3","title":"STREET ADDRESS 38 Yorston Street, Warners Bay 2282","text":"","stage":"general","stage_basis":"heading","page":3},{"label":"4","code":null,"number":"4","title":"APPLICANT/OWNER Lake Macquarie City Council","text":"Lake Macquarie City Council","stage":"general","stage_basis":"heading","page":3},{"label":"5","code":null,"number":"5","title":"TYPE OF REGIONAL","text":"DEVELOPMENT Council related development over $5 million","stage":"general","stage_basis":"heading","page":3},{"label":"6","code":null,"number":"6","title":"RELEVANT MANDATORY","text":"CONSIDERATIONS\n• Environmental planning instruments:\no State Environmental Planning Policy (Resilience and Hazards)\n2021\no State Environmental Planning Policy (Planning Systems) 2021\no State Environmental Planning Policy (Transport and\nInfrastructure) 2021\no State Environmental Planning Policy (Industry and Employment)\n2021\no Lake Macquarie Local Environmental Plan 2014\n• Draft environmental planning instruments: Nil\n• Development control plans:\no Lake Macquarie Development Control Plan 2014\n• Planning agreements: Nil\n• Provisions of the Environmental Planning and Assessment Regulation\n2021:\n• Coastal zone management plan: Nil\n• The likely impacts of the development, including environmental\nimpacts on the natural and built environment and social and economic\nimpacts in the locality\n• The suitability of the site for the development\n• Any submissions made in accordance with the Environmental Planning\nand Assessment Act 1979 or regulations\n• The public interest, including the principles of ecologically sustainable\ndevelopment","stage":"general","stage_basis":"heading","page":3},{"label":"7","code":null,"number":"7","title":"MATERIAL CONSIDERED BY","text":"THE PANEL\n• Council assessment report: 2 July 2024\n• Council memo: 5 July 2024\n• Council memo received: 9 July 2024\n• Written submissions during public exhibition: 6\n• Total number of unique submissions received by way of objection: 6","stage":"general","stage_basis":"heading","page":3},{"label":"8","code":null,"number":"8","title":"MEETINGS, BRIEFINGS AND","text":"SITE INSPECTIONS BY THE\nPANEL\n• Preliminary Briefing: 31 August 2023\no Panel members: Alison McCabe (Chair), Tony McNamara\no Council assessment staff: Andrew Leese, Amy Regado, Jim Suters\no Applicant Representatives: Marina Budisavljevic, James Walters,\nJess Salvador\no Department: Leanne Harris, Holly McCann\n• Site inspection Panel Members\no Alison McCabe (Chair): 1 July 2024\no Tony McNamara: 21 June 2024\no Roberta Ryan: 16 June 2024\n• Final briefing to discuss Council’s recommendation: 2 July 2024\no Panel members: Alison McCabe (Chair), Roberta Ryan, Tony\nMcNamara\no Council assessment staff: Andrew Leese, Amy Regado, Glen\nMathews and Jim Suters\no Applicant representatives: James Walters, Marina Budisavljevic\no Department: Leanne Harris, Holly McCann","stage":"general","stage_basis":"heading","page":3},{"label":"9","code":null,"number":"9","title":"COUNCIL","text":"RECOMMENDATION Approval","stage":"general","stage_basis":"heading","page":4},{"label":"10","code":null,"number":"10","title":"DRAFT CONDITIONS Attached to the Council assessment report","text":"DA/1127/2023\nSCHEDULE 2\nTerms and Reasons for Conditions\nUnder section 88(1)(c) of the EP&A Regulation, the consent authority must provide the terms of\nall conditions and reasons for imposing the conditions other than the conditions prescribed\nunder section 4.17(11) of the EP&A Act. The terms of the conditions and reasons are set out\nbelow.","stage":"general","stage_basis":"heading","page":4},{"label":"1","code":null,"number":"1","title":"Compliance with Building Code of Australia and insurance requirements","text":"under Home Building Act 1989\n1. It is a condition of a development consent for development that involves building\nwork that the work must be carried out in accordance with the requirements of\nthe Building Code of Australia.\n2. It is a condition of a development consent for development that involves residential\nbuilding work for which a contract of insurance is required under the Home\nBuilding Act 1989, Part 6 that a contract of insurance is in force before building\nwork authorised to be carried out by the consent commences.\n3. It is a condition of a development consent for a temporary structure used as an\nentertainment venue that the temporary structure must comply with Part B1 and\nNSW Part H102 in Volume 1 of the Building Code of Australia.\n4. In subsection (1), a reference to the Building Code of Australia is a reference to the\nBuilding Code of Australia as in force on the day on which the application for the\nconstruction certificate was made.\n5. In subsection (3), a reference to the Building Code of Australia is a reference to the\nBuilding Code of Australia as in force on the day on which the application for\ndevelopment consent was made.\n6. This section does not apply-\na. to the extent to which an exemption from a provision of the Building Code\nof Australia or a fire safety standard is in force under the Environmental\nPlanning and Assessment (Development Certification and Fire Safety)\nRegulation 2021, or\nb. to the erection of a temporary building, other than a temporary structure to\nwhich subsection (3) applies.","stage":"general","stage_basis":"heading","page":5},{"label":"2","code":null,"number":"2","title":"Erection of signs","text":"1. This section applies to a development consent for development involving building\nwork, subdivision work or demolition work.\n2. It is a condition of the development consent that a sign must be erected in a\nprominent position on a site on which building work, subdivision work or demolition\nwork is being carried out-\nDA/1127/2023\na. showing the name, address and telephone number of the principal certifier\nfor the work, and\nb. showing the name of the principal contractor, if any, for the building work\nand a telephone number on which the principal contractor may be\ncontacted outside working hours, and\nc. stating that unauthorised entry to the work site is prohibited.\n3. The sign must be-\na. maintained while the building work, subdivision work or demolition work is\nbeing carried out, and\nb. removed when the work has been completed.\n4. This section does not apply in relation to-\na. building work, subdivision work or demolition work carried out inside an\nexisting building, if the work does not affect the external walls of the\nbuilding, or\nb. Crown building work certified to comply with the Building Code of Australia\nunder the Act, Part 6.","stage":"general","stage_basis":"heading","page":5},{"label":"3","code":null,"number":"3","title":"Approved plans and supporting documentation","text":"Development must be carried out in accordance with the following approved plans and\ndocuments, except where the conditions of this consent expressly require otherwise.\nPlan\nnumber\nRevision\nnumber\nPlan title Date of plan\nA00 Rev C Drawing List and Site Location 31.01.2024\nA03 Rev C Proposed Site Plan 31.01.2024\nA10 Rev C Ground Floor & L1 Plan 31.01.2024\nA11 Rev C Roof Plan 31.01.2024\nA12 Rev C Car Park and Waste Plan 31.01.2024\nA30 Rev C Building Elevations 31.01.2024\nA31 Rev C Street Elevations 31.01.2024\nA40 Rev C Building Sections 31.01.2024\nA70 Rev C Material and Fence Selection 31.01.2024\nA71 Rev C Signage and Internal Concept 31.01.2024\nA73 Rev B External Perspectives 31.01.2024\nL001 Rev E Cover Sheet 21.12.2023\nDA/1127/2023\nL003 Rev E Overall Site Plan 21.12.2023\nL004 Rev E Detail Plan - Outdoor Courtyard / Play area 21.12.2023\nL005 Rev E Design Themes Play Space 21.12.2023\nL006 Rev E Planting Palette 21.12.2023\nApproved documents\nDocument title Version\nnumber\nPrepared by Date of document\nAccess Report LP_23131 Lindsay Perry\nAccess\n26 June 2023\nAcoustic Report MAC231829-\n01RP1V1\nMuller Acoustic\nConsulting\nJune 2023\nGeotechnical\nAssessment Report -\n24000483.001A Kleinfelder 22 June 2023\nDetailed Site\nInvestigation\n24000483.001A Kleinfelder 31 October 2023\nRemediation Action\nPlan\nGR00146-GR1 Green Room 20 June 2024\nWaste Management\nPlan -\nLMCC (Team\nLeader Building\nDesign)\n30 July 2023\nTraffic Report -\nTraffic & Parking\nAssessment -\nIntersect Traffic June 2023 and 1 December\n2023\nIn the event of any inconsistency with the approved plans and a condition of this consent,\nthe condition prevails.","stage":"general","stage_basis":"heading","page":6},{"label":"4","code":null,"number":"4","title":"Construction Certificate","text":"Prior to the commencement of building work a Construction Certificate shall be obtained.","stage":"general","stage_basis":"heading","page":7},{"label":"5","code":null,"number":"5","title":"Disability Access Requirements","text":"DA/1127/2023\nAccess for people with disabilities shall be provided from the buildings to kerb ramps and\nfootpaths along the street frontage, by means of a continuous path of travel in accordance\nwith Australian Standard AS 1428.1.\nNote: Additional legislation exists to promote the provision of services, which enable\npeople with a disability to maximise their potential, further their integration in the\ncommunity and achieve positive outcomes.\nThe following legislation may be relevant:\na) The NSW Disability Services Act 1993,\nb) The Commonwealth Disability Discrimination Act 1992,\nc) NSW Anti-Discrimination Act 1977.\nFor further information please consult:\na) Human Rights and Equal Opportunity Commission,\nb) NSW Anti-Discrimination Board.","stage":"general","stage_basis":"heading","page":7},{"label":"6","code":null,"number":"6","title":"Erosion and sediment controls in place","text":"Before any site work commences, the Certifier, must be satisfied the erosion and\nsediment controls in the erosion and sediment control plan are in place. These controls\nmust remain in place until any bare earth has been restabilised in accordance with\n'Managing Urban Stormwater: Soils and construction’ prepared by Landcom (the Blue\nBook) (as amended from time to time).","stage":"general","stage_basis":"heading","page":8},{"label":"7","code":null,"number":"7","title":"Occupation Certificate","text":"The development shall not be occupied or used prior to the issue of a Whole Occupation\nCertificate or a Part Occupation Certificate by the Principal Certifier.","stage":"general","stage_basis":"heading","page":8},{"label":"8","code":null,"number":"8","title":"Public Domain Works","text":"The landscape consultant that prepared the Public Works Certificate landscape\nconstruction plans (or a consultant with equivalent qualifications) shall submit Landscape\nMaintenance Reports to LMCC Senior Project Officer (Civil) at 52 weeks and 104 weeks\nafter practical completion certifying the public domain works are being satisfactorily\nmaintained.\nDA/1127/2023","stage":"general","stage_basis":"heading","page":8},{"label":"9","code":null,"number":"9","title":"Crime Prevention","text":"Closed-Circuit Television System (CCTV) to comply with Australian Standard - Closed\nCircuit Television System (CCTV) AS 4806.1/2/3/4 shall be installed. The system\nshall receive, hold or process data for the identification of people involved in anti-social or\ncriminal behaviour. The system is obliged to conform with Federal and State Privacy and\nSurveillance Legislation. Digital or analogue technology shall be used to receive, store\nand process data.\nLighting shall be designed in accordance with AS 1158.3.1 to provide appropriate lamps\nand lighting levels to mitigate pedestrian crime risk and fear, facilitating a safe,\ncomfortable visual environment for pedestrian and wheeled transport movement at night.\nWhere damaged or broken, lighting shall be repaired within 48 hours.\nRobust and vandal-proof finishes and fixtures including fencing, seating and signage\nincluding graffiti resistant building materials and fixtures shall be used in the construction\nof the development. Graffiti shall be removed within 24 hours of its appearance","stage":"general","stage_basis":"heading","page":9},{"label":"10","code":null,"number":"10","title":"Equal access to the premises","text":"Before the issue of a construction certificate, plans which demonstrate that adequate\naccess to the premises will be provided for persons with disabilities in accordance with\nthe Commonwealth Disability (Access to Premises - Buildings) Standards 2010. These\nplans must be submitted to the certifier.","stage":"before_cc","stage_basis":"heading","page":9},{"label":"11","code":null,"number":"11","title":"Erosion and sediment control plan","text":"Before the issue of a Construction Certificate, an erosion and sediment control plan must\nbe prepared by a suitably qualified person in accordance with the following documents\nand provided to the Certifier:\n1. Council’s relevant development control plan,\n2. the guidelines set out in 'Managing Urban Stormwater: Soils and Construction’\nprepared by Landcom (the Blue Book) (as amended from time to time), and\n3. the ‘Do it Right On-Site, Soil and Water Management for the Construction\nIndustry' (Southern Sydney Regional Organisation of Councils and the Natural\nHeritage Trust) (as amended from time to time).\nDA/1127/2023","stage":"before_cc","stage_basis":"heading","page":9},{"label":"12","code":null,"number":"12","title":"Preparation of construction and fit out plans for food and drink premises","text":"Before the issue of a construction certificate, detailed plans of all food and beverage\npreparation, serving and storage areas (including for perishable stock, waste, chemicals\nand personal belongings) must be prepared by a suitably qualified person.\nThe detailed plans must be prepared in accordance with the following editions in force on\nthe date of determination and provided to the certifier:\n1. Food Standards Code (Australia and Food Safety Standard 3.2.3 - Food\nPremises and Equipment\n2. Food Act 2003 and Food Regulation 2015\n3. Australian Standard 4674:2004 :Design, Construction and Fit-out of Food\nPremises\n4. Plumbing Code of Australia and Australian Standard/New Zealand Standard\nAS/NZS 3500 series on Plumbing and Drainage\n5. Hunter Water commercial trade wastewater requirements for food premises, and\n6. any relevant Water Services Association of Australia codes of practice, guidelines,\npolicies and requirements.","stage":"before_cc","stage_basis":"heading","page":10},{"label":"13","code":null,"number":"13","title":"Car parking details","text":"Before the issue of a Construction Certificate, written evidence prepared by a suitably\nqualified engineer must be obtained that demonstrates, to the certifier’s satisfaction, the\nplans for parking facilities comply with the relevant parts of AS 2890 Parking Facilities set\nand the relevant section of Council’s development control plan (in force as at the date of\ndetermination of this consent).\nThe proposed motor bike space shall be removed.","stage":"before_cc","stage_basis":"heading","page":10},{"label":"14","code":null,"number":"14","title":"Contributions Plan - Glendale Contributions Catchment - 2015","text":"In accordance with the provisions of the Environmental Planning and Assessment Act\n1979 - Sect 7.11 and the Lake Macquarie City Council Development Contributions Plan\nGlendale Contributions Catchment - 2015, the monetary contributions in the attached\nContributions Schedule shall be paid to Council for the purposes identified in that\nSchedule.\nFrom the date this determination is made until payment, the amounts of the contributions\npayable under the preceding clause shall be indexed and adjusted on:\na. 14 August,\nb. 14 November,\nc. 14 February, and\nd. 14 May;\nDA/1127/2023\nin each year in accordance with indexation provisions within the Contributions Plan and\nDirections issued under the Environmental Planning and Assessment Act 1979 - Sect\n7.17. The first date for indexation shall occur on the first abovementioned date after the\nnotice of determination becomes effective.\nThe contributions payable shall be the amounts last indexed and adjusted in accordance\nwith the above. However, if no amount has been indexed and adjusted because the first\ndate for indexation and adjustment has not arrived, the contributions payable shall be\nthose as set out in the table below.\nThe contributions shall be paid to Council as follows:\n1. Development applications involving subdivision - prior to the release of the\nSubdivision Certificate.\n2. Development applications involving building work - prior to the release of the first\nConstruction Certificate.\n3. Development applications involving both subdivision and building work - prior to\nthe release of the Subdivision Certificate or first Construction Certificate,\nwhichever occurs first.\n4. Development applications where no Construction Certificate or Subdivision\nCertificate is required - prior to the release of the development consent or prior to\nissue of the first Certificate of Occupancy, whichever occurs first.\n5. Complying Development Certificates - prior to any work authorised by the\napplication or certificate commencing.\nPlease note that should payment be made by cheque or electronic transfer the release of\nany documentation shall be subject to the clearing of those funds.\nIt is the professional responsibility of the Certifying Authority to ensure the monetary\ncontributions have been paid to Council in accordance with the above provisions.\nPlease note that should payment be made by cheque or electronic transfer the release of\nany documentation shall be subject to the clearing of those funds.\nIndexation details are available from Council’s Development Contribution Section.\nA copy of the Lake Macquarie City Council Development Contributions Plan Glendale\nContributions Catchment - 2015 is available on Council’s website, or a copy is available\nat the Council’s Administrative Building during Council’s opening hours.","stage":"before_cc","stage_basis":"heading","page":10},{"label":"15","code":null,"number":"15","title":"Development Street Addressing","text":"Application shall be made to Council to obtain addressing for the development in\naccordance with the guidelines in the NSW Address Policy and User Manual. Application\nis made by emailing an approved site plan, floor plan(s) and contact details to Data and\nKnowledge Management at enar@lakemac.nsw.gov.au.","stage":"before_cc","stage_basis":"heading","page":11},{"label":"16","code":null,"number":"16","title":"Acoustic Certification - Internal Comfort Noise Levels","text":"The proposed development is to be designed and constructed to comply with\nAS2107.2000 Acoustics - Recommended design sounds levels and reverberation times\nfor building interiors.\nA suitably qualified acoustic consultant shall be engaged to assist with the preparation of\nthe final building plans and specifications to ensure the proposed development will\ncomply with AS2107.2000.","stage":"before_cc","stage_basis":"heading","page":12},{"label":"17","code":null,"number":"17","title":"Concrete Footpath","text":"A design plan for concrete footpaths 1.5 metres wide along the full length of the street\nfrontage shall be submitted. Concrete foot paving shall be constructed in accordance with\nLake Macquarie City Council standard drawing EGSD-301 which is available from\nCouncils website. No works shall commence prior to the issue of a Public Works\nCertificate in accordance with s138 of the Roads Act 1993. Any works on a public road\nshall be approved by Council.","stage":"before_cc","stage_basis":"heading","page":12},{"label":"18","code":null,"number":"18","title":"Show Lots Clear of 100 Year Flood Level","text":"Stormwater designs and calculations shall be submitted to show that all lots are clear of\nthe 1:100 year flood level. This condition shall also apply to lots which would be affected\nby substantial overland flow, which may necessitate the carrying out of works to ensure\nproperly drained and flood free conditions.\nNote: Lots that are not 500mm clear of the 1:100 year flood level shall be subject to floor\nheight control and shall be identified as Flood Control Lots.","stage":"before_cc","stage_basis":"heading","page":12},{"label":"19","code":null,"number":"19","title":"Stormwater Disposal - Detention and Harvesting","text":"A Stormwater Detention and Harvesting Plan shall be submitted. The plan shall be\ngenerally in accordance with the plans approved by the Development Consent prepared\nby Northrop Newcastle, Civil Engineering Package, Ref: Job No. NL230571 - Revisions\nand Sheets as noted, last Issue E dated 25/01/2024. The stormwater plans approved by\nthis development consent are not approved for construction. The stormwater plans shall\ncomply with the following:\n1. Stormwater shall be disposed of through a piped system designed in accordance\nwith Australian Standard AS 3500 by a suitably qualified professional. The design\nshall be undertaken by a practicing Civil Engineer deemed to be suitably\nexperienced by Council and qualified so as to be accepted as a Member of the\nInstitution of Engineers Australia or a Registered Surveyor deemed to be suitably\nexperienced by Council shall be accepted as qualified to prepare plans for\ndrainage works (excluding flood control structures and bridges). Qualifications\ndemonstrating the above may be requested by Council. Stormwater detention\nmeasures shall be designed to ensure the development does not increase\nDA/1127/2023\nupstream or downstream flood levels for all recurrence intervals up to and\nincluding the 1% Annual Exceedance Probability.\n2. Detention storage shall be calculated and designed in accordance with Australian\nRainfall and Runoff 2019 and the Lake Macquarie City Council guideline -\nHandbook for Drainage Design Criteria and shall conform to the specifications and\nstandards contained in Development Control Plan 2014 Engineering Guidelines.\n3. Stormwater harvesting measures shall be designed in accordance with the\nDevelopment Control Plan 2014 Water Cycle Management Guideline. Stormwater\ndrainage plans shall include details of the harvesting system, including rainwater\ntank details, pump details and reticulation diagrams.\n4. The location of a permanent metal sign (minimum dimensions 150mm x 220mm)\nshall be detailed on the plans in a visible location near the detention orifice plate\nor onsite detention entry with the following wording:\nTHIS IS AN ONSITE STORMWATER DETENTION SYSTEM REQUIRED BY LAKE\nMACQUARIE CITY COUNCIL.\nIt is an offence to reduce the volume of the tank or basin or to interfere with the orifice\nplate that controls the outflow.\nThe base of the outlet control pit and the debris screen shall be cleaned of debris and\nsediment on a regular basis.\nThis plate shall not be removed.","stage":"before_cc","stage_basis":"heading","page":12},{"label":"20","code":null,"number":"20","title":"Compliance with the Geotechnical report","text":"All recommendations contained in the Geotechnical Report No. 24000483.001A\nRef:NCA23R154136 prepared by Kleinfelder Australia P/L dated 22/06/2023 shall be\nincorporated into the engineering design for the development. All works proposed to be\nundertaken shall embody the relevant recommendations of the Geotechnical Report.\n1. All engineering plans shall be endorsed by a suitably qualified Geotechnical\nConsultant. The endorsement shall state that the proposed works are in\naccordance with the recommendations of the aforementioned Geotechnical\nReport.","stage":"before_cc","stage_basis":"heading","page":13},{"label":"21","code":null,"number":"21","title":"Revised pedestrian entrance into the development","text":"Revised plans for pedestrian entry into the development from Holt Street shall be\nsubmitted to Council for approval.\nThe plans shall include, but not be limited to, at-grade gated access to be provided from\nHolt Street to the main pedestrian entrance into the building.\nDA/1127/2023","stage":"before_cc","stage_basis":"heading","page":13},{"label":"22","code":null,"number":"22","title":"Dilapidation report","text":"Before any site work commences, a dilapidation report must be prepared by a suitably\nqualified engineer detailing the structural condition of adjoining buildings, structures or\nworks and public land, to the satisfaction of the Certifier.\nWhere access has not been granted to any adjoining properties to prepare the dilapidation\nreport, the report must be based on a survey of what can be observed externally and\ndemonstrate, in writing, to the satisfaction of the Certifier, that all reasonable steps were\ntaken to obtain access to the adjoining properties.\nNo less than seven (7) days before any site work commences, adjoining building owner(s)\nmust be provided with a copy of the dilapidation report for their property(ies) and a copy of\nthe report(s) must be provided to Council (where Council is not the principal certifier) at\nthe same time.","stage":"before_work","stage_basis":"heading","page":14},{"label":"23","code":null,"number":"23","title":"Erosion and sediment controls in place","text":"Before any site work commences, the certifier, must be satisfied the erosion and\nsediment controls in the erosion and sediment control plan are in place. These controls\nmust remain in place until any bare earth has been restabilised in accordance with\n'Managing Urban Stormwater: Soils and Construction’ prepared by Landcom (the Blue\nBook) (as amended from time to time).","stage":"before_work","stage_basis":"heading","page":14},{"label":"24","code":null,"number":"24","title":"Works Within a Public Road Reserve","text":"Approval is granted to open a grassed or natural surface within the road reserve for the\ninstallation of all water services, cables, or mains. Upon completion of the work, the road\nreserve shall be restored to its original state and no hazards shall remain that may impact\non the public.\nFor any other works within the road reserve, an approval under Section 138 of the Roads\nAct 1993 shall be obtained from Council. The road shall not be opened until the approval\nhas been issued.","stage":"before_work","stage_basis":"heading","page":14},{"label":"25","code":null,"number":"25","title":"Contaminated Land Remediation Action Plan","text":"Prior to construction commencing, a revised Remediation Action Plan (RAP) shall be\nprepared, and a copy of the RAP provided to Council for approval.\nThe RAP shall be prepared by a suitably qualified and experienced contaminated land\nconsultant, to the satisfaction of Council and in accordance with:\nDA/1127/2023\n1. Guidelines for Consultants Reporting on Contaminated Sites (NSW Environment\nProtection Authority 2020, or as amended).\n2. Managing Land Contamination Planning Guidelines SEPP 55-Remediation of\nLand (Department of Urban Affairs and Planning and NSW EPA 1998, or as\namended).","stage":"before_work","stage_basis":"heading","page":14},{"label":"26","code":null,"number":"26","title":"Construction Site Management Plan","text":"Before the construction commences, a construction site management plan must be\nprepared, and provided to the certifier. The plan must include the following matters:\na. The location and materials for protective fencing and hoardings on the perimeter of\nthe site;\nb. Provisions for public safety;\nc. Pedestrian and vehicular site access points and construction activity zones;\nd. Details of construction traffic management including:\ni. Proposed truck movements to and from the site;\nii. Estimated frequency of truck movements; and\niii. Measures to ensure pedestrian safety near the site;\ne. Details of bulk earthworks to be carried out;\nf. The location of site storage areas and sheds;\ng. The equipment used to carry out works;\nh. The location of a garbage container with a tight-fitting lid;\ni. Dust, noise and vibration control measures;\nj. The location of temporary toilets;\nk. The protective measures for the preservation of trees on-site and in adjoining\npublic areas including measures in accordance with:\ni. AS 4970 - Protection of trees on development sites;\nii. An applicable Development Control Plan;\niii. An arborist’s report approved as part of this consent\nA copy of the construction site management plan must be kept on-site at all times while\nwork is being carried out.","stage":"before_work","stage_basis":"heading","page":15},{"label":"27","code":null,"number":"27","title":"Pre-clearance fauna surveys","text":"DA/1127/2023\nImmediately prior to clearing, a suitably qualified Ecologist or wildlife carer shall undertake\npre-clearing surveys to identify fauna habitats present on site that will require attention\nduring clearing works. Pre-clearing surveys are to include (but not limit to):\n• Inspection of hollow bearing trees.\n• Inspection of vegetation for nests / dreys.\n• Inspection of debris piles, including coarse woody debris.\n• Identification of any hollow bearing trees / nest trees to be retained.","stage":"before_work","stage_basis":"heading","page":15},{"label":"28","code":null,"number":"28","title":"Removal of fauna habitat","text":"A suitable qualified ecologist or wildlife carer shall supervise removal of any fauna habitat\nto ensure mitigation against any native animal welfare issues.\nRemoval of trees with habitat hollows and / or nests shall be undertaken at a time that\nminimises impact to fauna, particularly threatened fauna that could breed and or hibernate\nwithin hollows /nests on site (i.e., preferably March, April, September, or October).\nWhere possible, trees with habitat hollows and / or nests shall be removed at least 24\nhours after other vegetation approved for removal to encourage any residing fauna to\nrelocate.\nAny hollow-bearing trees shall be felled in one to two metre sections, beginning at the top\nof the crown. Lengths cut from the trees shall be in a manner that shall preserve the\nhollows with each section inspected and appropriately treated to minimise impact to fauna.\nClearing shall be staged, where possible, from areas of most impact to areas of least\nimpact to help guide fauna into areas of bushland that are to be retained.","stage":"before_work","stage_basis":"heading","page":16},{"label":"29","code":null,"number":"29","title":"Hours of work","text":"Site work must only be carried out between the following times -\n7:00am to 6:00pm Monday to Friday\n7:00am to 5:00pm Saturday\nSite work is not to be carried out outside of these times except where there is an\nemergency, or for urgent work directed by a police officer or a public authority.\nDA/1127/2023","stage":"during_work","stage_basis":"heading","page":16},{"label":"30","code":null,"number":"30","title":"Soil management","text":"While site work is being carried out, the certifier must be satisfied all soil removed from or\nimported to the site is managed in accordance with the following requirements:\na. All excavated material removed from the site must be classified in accordance with\nthe EPA’s Waste Classification Guidelines before it is disposed of at an approved\nwaste management facility and the classification, and the volume of material\nremoved must be reported to the principal certifier.\nb. All fill material imported to the site must be:\na. Virgin Excavated Natural Material as defined in Schedule 1 of the\nProtection of the Environment Operations Act 1997; or\nb. a material identified as being subject to a resource recovery exemption by\nthe NSW EPA; or\nc. a combination of Virgin Excavated Natural Material as defined in Schedule\n1 of the Protection of the Environment Operations Act 1997 and a material\nidentified as being subject to a resource recovery exemption by the NSW\nEPA.","stage":"during_work","stage_basis":"heading","page":17},{"label":"31","code":null,"number":"31","title":"Waste management","text":"While site work is being carried out:\n1. all waste management must be undertaken in accordance with the waste\nmanagement plan; and\n2. upon disposal of waste, records of the disposal must be compiled and provided\nto the principal certifier, detailing the following:\na. The contact details of the person(s) who removed the waste;\nb. The waste carrier vehicle registration;\nc. The date and time of waste collection;\nd. A description of the waste (type of waste and estimated quantity) and\nwhether the waste is to be reused, recycled or go to landfill;\ne. The address of the disposal location(s) where the waste was taken;\nf. The corresponding tip docket/receipt from the site(s) to which the waste is\ntransferred, noting date and time of delivery, description (type and quantity)\nof waste.\nIf waste has been removed from the site under an EPA Resource Recovery Order or\nExemption, records in relation to that Order or Exemption must be maintained and\nprovided to the principal certifier and Council.\nDA/1127/2023","stage":"during_work","stage_basis":"heading","page":17},{"label":"32","code":null,"number":"32","title":"Noise and Vibration requirements","text":"While site work is being carried out, noise generated from the site must not exceed an\nLAeq (15 min) of 5dB(A) above background noise, when measured at a lot boundary of\nthe site.","stage":"during_work","stage_basis":"heading","page":18},{"label":"33","code":null,"number":"33","title":"Site Amenities","text":"Toilet facilities shall be available or provided at the work site before works begin and shall\nbe maintained until the works are completed at a ratio of one toilet plus one additional\ntoilet for every 20 persons employed at the site.\n1. Each toilet shall: be a standard flushing toilet connected to a public sewer, or\n2. have an approved on-site effluent disposal system under the Local Government\nAct 1993, or\n3. be a temporary chemical closet.","stage":"during_work","stage_basis":"heading","page":18},{"label":"34","code":null,"number":"34","title":"Unobstructed Footpath Access","text":"The person having the benefit of the consent shall maintain unobstructed footpath access\nwithin the public road reserve at all times. Building materials shall not be placed or stored\nwithin the road reserve.\nIn the case of sites where it is not possible to keep the footpath or road reserve clear\nduring construction works approval from Council shall be obtained prior to any closing of\nthe road reserve or footpath area. An application for temporary structure or occupation of\nroad reserve should be submitted via Council’s website.","stage":"during_work","stage_basis":"heading","page":18},{"label":"35","code":null,"number":"35","title":"Completion of landscape and tree works","text":"Before the issue of an Occupation Certificate, the principal certifier must be satisfied all\nlandscape and tree-works have been completed in accordance with approved plans and\ndocuments and any relevant conditions of this consent.","stage":"before_oc","stage_basis":"heading","page":18},{"label":"36","code":null,"number":"36","title":"Completion of public utility services","text":"Before the issue of the relevant occupation certificate, confirmation must be obtained from\nthe relevant authority that any adjustment or augmentation of any public utility services\nDA/1127/2023\nincluding gas, water, sewer, electricity, street lighting and telecommunications, required as\na result of the development, have been completed and this confirmation must be provided\nto the principal certifier.","stage":"before_oc","stage_basis":"heading","page":18},{"label":"37","code":null,"number":"37","title":"Food Premises Final Inspection","text":"Before the issue of an occupation certificate, the food premises shall be inspected by an\nAuthorised Officer of LMCC under the Food Act 2003, to determine compliance with the\nFood Act 2003, Food Safety Standards and Australian Standard 4674:2004: Design,\nConstruction and Fit-out of Food Premises.","stage":"before_oc","stage_basis":"heading","page":19},{"label":"38","code":null,"number":"38","title":"Post-construction dilapidation report","text":"Before the issue of an Occupation Certificate a post-construction dilapidation report must\nbe prepared by a suitably qualified engineer, to the satisfaction of the certifier, detailing\nwhether:\na. after comparing the pre-construction dilapidation report to the post-construction\ndilapidation report required under this condition, there has been any structural\ndamage to any adjoining buildings; and\nb. where there has been structural damage to any adjoining buildings, that it is a\nresult of the work approved under this development consent; and\nc. a copy of the post-construction dilapidation report must be provided to Council\n(where Council is not the principal certifier, or a principal certifier is not required)\nand to the relevant adjoining property owner(s).","stage":"before_oc","stage_basis":"heading","page":19},{"label":"39","code":null,"number":"39","title":"Removal of waste upon completion","text":"","stage":"before_oc","stage_basis":"heading","page":19},{"label":"40","code":null,"number":"40","title":"Repair of infrastructure","text":"","stage":"before_oc","stage_basis":"heading","page":19},{"label":"41","code":null,"number":"41","title":"Consolidation of Lots","text":"Prior to the issue of any Occupation Certificate, whichever occurs first, Lots Lot 1\nDP157444, Lot 380 DP1133165 and Lot 2 DP730502 shall be consolidated and registered\nat the NSW Land Registry Services and a copy of the registered plan shall be provided to\nCouncil.","stage":"before_oc","stage_basis":"heading","page":20},{"label":"42","code":null,"number":"42","title":"Driveway Construction","text":"Prior to the issue of the whole occupation certificate, the driveway to the garage or car\nparking area of the development shall be constructed in accordance with the approved\nconstruction certificate plan.","stage":"before_oc","stage_basis":"heading","page":20},{"label":"43","code":null,"number":"43","title":"Positive covenant for water quality device maintenance","text":"A maintenance schedule for the water quality device(s) detention and harvesting tank as\nshown on the stormwater plans by Northrop shall be completed by a suitably qualified\nengineer.\nThe maintenance schedule shall outline the required maintenance and timing intervals\n(e.g. monthly, quarterly etc.).\nA positive covenant shall be placed on title requiring the owner of the land to undertake\nperiodic maintenance for the water quality device(s) in accordance with the above\nmaintenance plan.\nNote: If during detailed design stage the water quality devices are substituted for a similar\nproduct the maintenance plan shall reference the adopted devices.","stage":"before_oc","stage_basis":"heading","page":20},{"label":"44","code":null,"number":"44","title":"Public Domain Works","text":"At the practical completion of works and prior to the issue of the Final Occupation\nCertificate, the landscape consultant that prepared the Public Works Certificate landscape\nconstruction plans shall submit a Landscape Compliance Report to the LMCC Senior\nDA/1127/2023\nProject Officer (Civil) certifying all public domain landscape works have received the\nrelevant witness and hold point inspections, implemented and maintained in accordance\nwith this Public Works Certificate. This compliance report is required prior to LMCC\nissuing a compliance certificate for the works.\nFor clarity, this condition includes all street tree planting shown on the approved\nlandscaping plans.","stage":"before_oc","stage_basis":"heading","page":20},{"label":"45","code":null,"number":"45","title":"Provision of Council Easement (Public)","text":"An easement to drain water, (minimum three metres wide or the width of the 100-year flow\npath, whichever is greater) shall be created at no cost to Council in favour of Council in\naccordance with the approved Stormwater Drainage Plan by Northrop Newcastle , Civil\nEngineering Package , Ref: Job No. NL230571 - Revisions and Sheets as noted, last\nIssue E dated 25/01/2024.\nThe easement shall be registered on the title of the lot under Section 88B of the\nConveyancing Act 1919 as amended. A copy of the registered Section 88B Instrument\nshall be provided to Council prior to the issue of any occupation certificate.\nCouncil shall be the authority with the power to release, vary or modify the terms of the\neasement.","stage":"before_oc","stage_basis":"heading","page":21},{"label":"46","code":null,"number":"46","title":"Acoustic Certification","text":"Plans shall be certified as being designed in accordance with the approved Acoustic\nReport reference Ref MAC231829-01RP1V1 prepared by Mueller Acoustic Consulting\ndated June 2023. Including construction and operational compliance with “Section 6.2\nNoise Attenuation Controls and Section 8 Construction Recommendations of the MAC\nAcoustic Report Ref MAC231829-01RP1V1 dated June 2023.","stage":"before_oc","stage_basis":"heading","page":21},{"label":"47","code":null,"number":"47","title":"Stormwater Disposal - Stormwater Detention and Harvesting","text":"All drainage works shall be carried out in accordance with the approved Construction\nCertificate plans.\nPrior to the issue of any Occupation Certificate, a Works As Executed Plan shall be\nprepared by a surveyor and submitted to the Certifying Authority that demonstrates\ncompliance with the approved Construction Certificate. If there are any changes from the\nConstruction Certificate these shall be highlighted in a different colour on the plan and\ncertification shall be provided from the design engineer, the changes do not affect the\nstormwater design outcomes.\nDA/1127/2023","stage":"before_oc","stage_basis":"heading","page":21},{"label":"48","code":null,"number":"48","title":"Contaminated Land Remediation and Validation","text":"A suitably qualified and experienced Contaminated Land Consultant shall validate the site\nhas been remediated. Validation shall be provided in accordance with the Guidelines for\nConsultants Reporting on Contaminated Sites (NSW Environment Protection Authority\n2020, or as amended). The validation report shall include a clear statement the consultant\nconsiders the site to be suitable for the approved use.\nNote: Certification from the person who carried out remediation works shall be provided to\nCouncil in accordance with the requirements of Clause 4.15 of Environmental Planning\nPolicy (Resilience and Hazards 2021) - Chapter 4 Remediation of land.","stage":"before_oc","stage_basis":"heading","page":22},{"label":"49","code":null,"number":"49","title":"External lighting during ongoing use","text":"During ongoing use of the premises, all lighting must be operated and maintained in\naccordance with the approved plans and the requirements of this consent.","stage":"ongoing","stage_basis":"heading","page":22},{"label":"50","code":null,"number":"50","title":"Graffiti removal","text":"During ongoing use of the premises, ensure graffiti is removed from the exterior of the\nbuilding or associated structures, including any fences, site services and retaining/planter\nbed walls.","stage":"ongoing","stage_basis":"heading","page":22},{"label":"51","code":null,"number":"51","title":"Storage and disposal of waste materials during ongoing use","text":"During ongoing use of the premises:\n1. bins must be put on the premises for the storage of any waste that is generated\n(including for recycling),\n2. all garbage and recyclable materials generated from the premises must be stored\nwholly within any approved storage area and must not be stored outside the\npremises (including any public place) at any time\n3. arrangements must be implemented for the separation of recyclable materials\nfrom garbage\n4. any approved waste storage area must be appropriately maintained to prevent\nlitter and the entry of pests\n5. where council does not provide commercial garbage and recyclable materials\ncollection services:\nDA/1127/2023\na. a contract must be entered into with a licensed contractor to provide these\nservices for the premises; and\nb. a copy of the contract must be kept on premises and provided to relevant\nauthorities including council officers on request.\n6. where the collection of garbage and recyclable materials from the premises is\nundertaken by a licensed contractor, it must only occur between daylight\nhours Monday to Saturday\n7. all liquid trade waste discharged to sewerage system must comply with the trade\nwaste approval issued by the relevant water authority\n8. all liquid trade waste pre-treatment devices must be regularly maintained to\nremain effective in accordance with the conditions of the liquid trade waste\napproval issued by the relevant water authority.","stage":"ongoing","stage_basis":"heading","page":22},{"label":"52","code":null,"number":"52","title":"Emissions","text":"There shall be no interference with the amenity of the neighbourhood by reason of the\nemission of any \"offensive noise\" as defined in the Protection of the Environment\nOperations Act 1997, vibration, smell, fumes, smoke, vapour, steam, soot, ash or dust, or\notherwise as a result of the development.","stage":"ongoing","stage_basis":"heading","page":23},{"label":"53","code":null,"number":"53","title":"External Storage of Products","text":"The external storage or display of any products on the development site is not permitted.","stage":"ongoing","stage_basis":"heading","page":23},{"label":"54","code":null,"number":"54","title":"Hours of Operation","text":"Following commencement of occupation, the premises shall operate or trade only\nbetween the times stated as follows:\nMondays to Fridays - 6:30am to 6:30pm\nSaturdays, Sundays and Public Holidays - Nil\nOther internal operations such as cleaning, preparation, and office administration may be\nundertaken outside of the above hours provided no disturbance to the amenity of the\nneighbourhood occurs.","stage":"ongoing","stage_basis":"heading","page":23},{"label":"55","code":null,"number":"55","title":"Landscape Works","text":"All landscape works required under this consent shall undergo an establishment\nmaintenance period of a minimum of 52 weeks.\nDA/1127/2023\nAll landscaping shall then be permanently maintained in good condition in accordance\nwith the approved landscape plan and the adopted Development Control Plan 2014\nGuidelines - Landscape Design Guidelines.\nFor clarity, this condition includes all street tree planting shown on the approved\nlandscaping plans.","stage":"ongoing","stage_basis":"heading","page":23},{"label":"56","code":null,"number":"56","title":"Lighting","text":"Any lighting shall be installed to comply with Australian Standard AS/NZS4282-2019.","stage":"ongoing","stage_basis":"heading","page":24},{"label":"57","code":null,"number":"57","title":"Noise - Ongoing Operation of Machinery, Plant and Equipment","text":"The Laeq (15 minute) operating noise level of machinery, plant, equipment, or any other\noperational noise source, when measured at the boundary of another premises, shall\ncomply with either the amenity or intrusiveness criteria calculated in accordance with the\nNSW Environment Protection Authority Noise Policy for Industry 2017.\nFor assessing amenity criteria, the area shall be categorised in accordance with the\nguidelines outlined in Chapter 2 of that Policy.","stage":"ongoing","stage_basis":"heading","page":24},{"label":"58","code":null,"number":"58","title":"Acoustic Certification","text":"At 90 days of operation a suitably qualified acoustic consultant shall test, measure and\ncertify the development is operating, at that time, in accordance with the approved\nAcoustic Report.","stage":"ongoing","stage_basis":"heading","page":24},{"label":"59","code":null,"number":"59","title":"Plan of Management","text":"An Operational Plan of Management shall be prepared and kept on premises. The\nOperational Plan of Management must include, but is not limited to, the following details:\n• Capacity and Hours of Operation\n• Staff and Administration Management\n• Measures for drop off and pick up arrangements\n• Arrivals and Departures for Staff\n• Car Parking\n• Education and Activities\n• A Procedure for Noise and Complaint Management\nDA/1127/2023\n• Evacuation Plan and Management, including procedures for people with a\ndisability.","stage":"ongoing","stage_basis":"heading","page":24},{"label":"60","code":null,"number":"60","title":"Waste Management Plan","text":"An ongoing Operational waste management plan for the development, as per Section 4\n(commercial use) of the 2019 Lake Macquarie Waste Management Guidelines, shall be\nprovided to and approved by Council Waste Services. The plan must include the\nfollowing additional matters:\na. Waste types and estimated volumes, use and destination, in accordance with the\n2019 Lake Macquarie Waste Management Guidelines sub-section 4.1 to include\nthe following information;\ni. the details of the businesses likely to be removing waste,\nii. an estimate of the type and quantity of waste,\niii. whether waste is expected to be reused, recycled or sent to landfill, and\niv. the address and EPA NSW licence numbers of the disposal locations for\ncompostables, recyclables and waste.\nb. That Council could provide a waste collection service from kerbside (optional);\nand\nc. Show storage space for a bin cart and installation of a recharge power point within\nthe waste storage room, if necessary.\nd. a service agreement must be in place with either Lake Macquarie City Council or\na privately-owned licensed waste collection services provider that will allow for\nwaste services to commence upon occupation of the development - this needs to\nbe arranged at least six (6) weeks prior to completion of the build or occupation to\nallow time for delivery of bins.","stage":"ongoing","stage_basis":"heading","page":25},{"label":"61","code":null,"number":"61","title":"Children and Staff Numbers","text":"The facility shall comply with the indoor and outdoor space requirements in the Education\nand Care Services National Regulations (the Regulations).\nThe maximum number of child care places shall comply with the numbers specified in the\nservice licence.\nShould there be any reduction in the outdoor or indoor spaces, then the number of\nchildren must be reduced accordingly to comply with the Regulations.\nThe staff to children ratios at the facility shall be in accordance with relevant\nlegislation/regulations.","stage":"ongoing","stage_basis":"heading","page":25},{"label":"62","code":null,"number":"62","title":"Car parking allocation","text":"DA/1127/2023\nCar parking shall be allocated and signposted or line marked in accordance with the\nfollowing:\n• 10 carparking spaces allocated to staff\n• 6 car parking spaces allocated to 15 minutes drop off and collection","stage":"ongoing","stage_basis":"heading","page":25}]});
